  'Armor of Invulnerability': { name: 'Доспех неуязвимости', description: 'Вы получаете сопротивление немагическому урону. Кроме того, действием можно получить иммунитет к немагическому урону на 10 минут.' },
  'Armor of Vulnerability': { name: 'Доспех уязвимости', description: 'Этот проклятый доспех даёт сопротивление одному виду урона, но уязвимость к двум другим.' },
  'Armor of Resistance': { name: 'Доспех сопротивления', description: 'Пока вы носите этот доспех, вы получаете сопротивление одному виду урона.' },
  'Plate Armor of Etherealness': { name: 'Латный доспех эфирности', description: 'Пока вы носите этот доспех, действием можно наложить на себя заклинание Эфирность.' },
  'Plate Armor of Resistance': { name: 'Латный доспех сопротивления', description: 'Пока вы носите этот латный доспех, вы получаете сопротивление одному виду урона.' },
  'Smoldering Armor': { name: 'Тлеющий доспех', description: 'Пока этот доспех надет, от него поднимаются безвредные клубы дыма без запаха.' },
  'Armor, +1': { name: 'Доспех +1', description: 'Пока вы носите этот доспех, вы получаете бонус +1 к КД.' },
  'Armor, +2': { name: 'Доспех +2', description: 'Пока вы носите этот доспех, вы получаете бонус +2 к КД.' },
  'Armor, +3': { name: 'Доспех +3', description: 'Пока вы носите этот доспех, вы получаете бонус +3 к КД.' },
  'Adamantine Armor (Chain Mail)': { name: 'Адамантиновый доспех (кольчуга)', description: 'Кольчуга, усиленная адамантином. Критические попадания по вам становятся обычными.' },
  'Adamantine Armor (Chain Shirt)': { name: 'Адамантиновый доспех (кольчужная рубаха)', description: 'Кольчужная рубаха, усиленная адамантином. Критические попадания по вам становятся обычными.' },
  'Adamantine Armor (Scale Mail)': { name: 'Адамантиновый доспех (чешуйчатый)', description: 'Чешуйчатый доспех, усиленный адамантином. Критические попадания по вам становятся обычными.' },
  'Adamantine Armor (Breastplate)': { name: 'Адамантиновый доспех (кираса)', description: 'Кираса, усиленная адамантином. Критические попадания по вам становятся обычными.' },
  'Adamantine Armor (Splint)': { name: 'Адамантиновый доспех (наборный)', description: 'Наборный доспех, усиленный адамантином. Критические попадания по вам становятся обычными.' },
  'Adamantine Armor (Half Plate)': { name: 'Адамантиновый доспех (полулаты)', description: 'Полулаты, усиленные адамантином. Критические попадания по вам становятся обычными.' },
  'Adamantine Armor (Plate)': { name: 'Адамантиновый доспех (латы)', description: 'Латный доспех, усиленный адамантином. Критические попадания по вам становятся обычными.' },
  'Armor, +1 (Chain Mail)': { name: 'Доспех +1 (кольчуга)', description: 'Пока вы носите эту кольчугу, вы получаете бонус +1 к КД.' },
  'Armor, +1 (Chain Shirt)': { name: 'Доспех +1 (кольчужная рубаха)', description: 'Пока вы носите эту кольчужную рубаху, вы получаете бонус +1 к КД.' },
  'Armor, +1 (Leather)': { name: 'Доспех +1 (кожаный)', description: 'Пока вы носите этот кожаный доспех, вы получаете бонус +1 к КД.' },
