  'Armor, +3 (Studded Leather)': { name: 'Доспех +3 (клёпаный кожаный)', description: 'Вы получаете бонус +3 к КД.' },
  'Armor, +3 (Breastplate)': { name: 'Доспех +3 (кираса)', description: 'Вы получаете бонус +3 к КД.' },
