  'Ioun Stone (Greater Absorption, Mastery, or Regeneration)': { name: 'Камень Йоун (высшее поглощение, мастерство или регенерация)', description: 'Бросьте 1к4, чтобы определить, какой именно легендарный камень Йоун вы получили.' },
  'Figurine of Wondrous Power (various)': { name: 'Фигурка чудесной силы (разные)', description: 'Бросьте к8 по дополнительной таблице фигурок, чтобы определить, в какое существо она превращается.' },
  "Quaal's Feather Token (Anchor, Fan, or Tree)": { name: 'Перьевой жетон Куаала (якорь, веер или дерево)', description: 'Крошечный предмет, который при активации создаёт одноразовый магический эффект.' },
  "Quaal's Feather Token (Bird, Swan Boat, or Whip)": { name: 'Перьевой жетон Куаала (птица, лодка-лебедь или кнут)', description: 'Крошечный предмет, который при активации создаёт одноразовый магический эффект.' },
